  "m.official.tip": "Oficial: el CN publicado por la FFCO (media de las mejores carreras, reescalado cada 1 de enero).",
  "m.top6w.tip": "Ozimut: una puntuación Ozimut por carrera (el valor Ozimut del recorrido — la media de los niveles habituales × tiempos de los más rápidos: el 90 % del pelotón en bosque, dos tercios en sprint — dividido por el tiempo del corredor) y después el índice Ozimut del corredor, la media ponderada de sus mejores carreras en 6 plazas. Calculado con los mismos resultados que el CN oficial.",
  "m.fair.tip": "El nivel habitual del corredor — la media ponderada de su 60 % de mejores puntuaciones Ozimut, sin límite de plazas —, con el que se mide el valor Ozimut de los recorridos.",
