  "rn.fed.rank": "{r} de {n}",
  "doc.country.none": "Ozimut aún no tiene clasificación para este país: el método y las mediciones que se presentan aquí son los de Francia, donde se desarrolló.",
  "doc.country.ES": "<b>En España.</b> El método Ozimut es el mismo que en Francia, con un ajuste medido en las carreras españolas (julio de 2025 – octubre de 2026, los mismos corredores): en bosque, el valor de un recorrido se calcula con los dos tercios más rápidos (en lugar del 90 %), lo que predice mejor la clasificación en 0,4 puntos de duelos. España no tiene un índice oficial del que partir: la primera temporada del archivo parte del nivel habitual de cada categoría respecto a M21, tal como se mide en Francia, y las carreras hacen el resto. Todos los corredores de las carreras españolas están clasificados, extranjeros incluidos. Con los mismos corredores, el índice Ozimut predice mejor quién termina delante que la regla de la FEDO aplicada el mismo día (tiempo del ganador de la categoría entre el del corredor, media de las 6 mejores carreras de 12 meses): +5,0 puntos de duelos en bosque, +5,4 en sprint. La clasificación de la FEDO se muestra tal como la publica, en la pestaña «Clasificación FEDO» de la clasificación. El estudio de abajo es el realizado en Francia.",
  "rk.tab.fed": "Clasificación {f}",
