  "dep.lede": "Carga el archivo de resultados exportado de tu programa de cronometraje. Se lee aquí, en tu navegador: no se envía nada. Ves enseguida los resultados y todos los análisis de los tiempos parciales y después eliges, si quieres, publicarlo en Ozimut.",
