  "os.help.best": "Lo mejor:",
  "os.help.best.text": "la exportación IOF XML 3.0 «StartList» de tu software (OE, MeOS, OS…); lo tiene todo, sin ambigüedad.",
  "os.help.csv": "CSV:",
  "os.help.csv.text": "una fila de cabecera y luego un corredor por fila. Columnas reconocidas, en cualquier orden: Start (o Heure, Départ), Surname (o Nom), First name (o Prénom; o el nombre completo en una columna), Club, Course (o Circuit), Class (o Catégorie). Con la hora y el nombre basta; sin columna Course, la lista se ordena por categoría. Separador punto y coma, coma o tabulador. Ejemplo:",
  "os.help.csv.example": "Course;Start;Surname;First name;Club;Class\nVioleta largo;10:00;DUPONT;Jeanne;0109;F21\nVioleta largo;10:02;MARTIN;Paul;7707;M35\nNaranja;10:01;LEROY;Léa;0111;F16",
  "os.help.csv.notes": "Horas como 10:02 o 10h02 (o 10:02:30). Club: su número, seguido si quieres de su nombre, ayuda a reconocer a los corredores. También se leen las exportaciones CSV de OE y MeOS.",
  "os.help.sheet": "Google Sheets:",
  "os.help.sheet.text": "pega el enlace de la hoja, compartida con «Cualquier persona con el enlace». Puede seguir la disposición CSV de arriba, o una cuadrícula: una fila con los nombres de los recorridos y luego una cabecera Start / Name / Club repetida para cada recorrido, una salida por fila:",
  "os.help.sheet.example": "         Violeta largo        Naranja\nStart    Name          Club   Name         Club\n10:00    Jeanne DUPONT 0109   Léa LEROY    0111\n10:02    Paul MARTIN   7707\nUna columna Start por recorrido también sirve.",
