  "sh.ocad.title": "Importar los recorridos de un archivo OCAD",
  "sh.ocad.intro": "Un proyecto de trazado de OCAD guarda los recorridos en un archivo y, casi siempre, el mapa en otro. Cada recorrido marcado se convierte en un recorrido del análisis: su mapa impreso con el trazado, sus controles colocados y su georreferenciación tomada del mapa. Un recorrido con el mismo nombre se sustituye.",
