  "ad.st.lede": "Los sitios de organizadores que hay que contactar: aquellos cuyo robots.txt prohíbe los robots (la recogida los lee igualmente, unas pocas solicitudes por carrera) y los que bloquean activamente a los robots (nunca se eluden: sus resultados no se leen). Para cada uno, las carreras afectadas.",
