  "vma.tab.apps": "Aplicaciones",
  "g.lede": "Juegos de entrenamiento de lectura de mapa, en mapas dibujados aquí mismo: cada partida inventa otros nuevos. No se envía nada; tus mejores puntuaciones se quedan en este navegador.",
  "g.best": "Mejor puntuación",
