  "ia.note": "Gratis, dentro de un límite de unas cien preguntas al día para todo el sitio (15 por persona y día; sin límite con tu propia clave, más abajo). La IA no ve los datos: escribe una consulta, que tu navegador ejecuta. Puede equivocarse: la interpretación elegida y la consulta se muestran bajo cada respuesta.",
