  "ia.byok.privacy": "La clave se queda en este navegador: nunca se envía a Ozimut (sin «Recordar», se borra al cerrar la pestaña; también se borra al cerrar sesión). El proveedor recibe la pregunta, la descripción de las tablas y tu número de licencia — nunca los datos —, según sus condiciones, y te cobra según sus tarifas (una pregunta cuesta desde menos de un céntimo hasta un céntimo aproximadamente). Crea una clave reservada para este uso, con un límite de gasto: un script de la página podría leerla.",
