  "ia.err.generic": "Error {status}",
  "byok.note.openrouter": "Una sola clave para la mayoría de los modelos (Claude, GPT, Gemini, Llama…), un tope de gasto por clave. Los modelos gratuitos están limitados a 50 solicitudes al día (1000 tras comprar 10 créditos) y 20 por minuto — una pregunta es una solicitud, dos si la consulta se corrige —; algunos de sus proveedores pueden usar las preguntas: consulta los ajustes de privacidad de tu cuenta de OpenRouter.",
