  "vma.note6": "Seis minutos es más o menos el tiempo que se aguanta a la VAM (de 4 a 11 minutos según el corredor, a menudo unos 6): el medio Cooper se corre a la VAM, si el ritmo ha sido regular.",
  "vma.note12": "Doce minutos es más de lo que se aguanta a la VAM (de 4 a 11 minutos según los estudios, a menudo unos 6): el Cooper se corre por debajo, hacia el 95 % de la VAM bien entrenado, el 90 % moderadamente entrenado, el 85 % poco entrenado; hacia el 97 a 99 % quienes la mantienen de 10 a 11 minutos. Hipótesis adoptada: {p} %. Estas partes son referencias de entrenadores, no constantes medidas: el medio Cooper da una VAM más directa.",
