  "rh.lede": "La historia de los dos grandes relevos de clubes de Francia: el Championnat de France des Clubs (CFC) desde 1999 y el Critérium National des Équipes (CNE) desde 2006 — clasificaciones completas, palmarés de los clubes, ediciones.",
