  "nav.descriptions": "Descripciones de control",
  "cd.title": "Descripciones de control",
  "cd.lede": "Los símbolos de las descripciones de control de la IOF, columna a columna, con su número, nombre y descripción tal como los da la especificación y, para el elemento del control, los símbolos de mapa que le hace corresponder.",
  "cd.lang": "Idioma de los textos",
  "cd.search": "Buscar",
  "cd.search.ph": "un nombre, una palabra, un número",
  "cd.practice": "Practicar",
