  "cd.practice.names": "Ocultar los nombres",
  "cd.practice.map": "Ocultar los símbolos",
  "cd.practice.sym": "Ocultar los dibujos del mapa",
  "cd.practice.hint": "Los nombres están ocultos: toca un símbolo para descubrir su nombre, otra vez para ocultarlo de nuevo.",
  "cd.practice.hint.map": "Solo se muestran los dibujos del mapa: imagina la descripción y luego toca el dibujo para descubrir el símbolo y su nombre, otra vez para ocultarlos de nuevo.",
  "cd.practice.hint.sym": "Solo se muestran los símbolos: imagina el elemento tal como lo dibuja el mapa y luego toca el símbolo para descubrir el mapa y el nombre, otra vez para ocultarlos de nuevo.",
  "cd.intro": "Leer una línea de descripciones",
  "cd.intro.hint": "Cada control tiene su línea de ocho casillas, que se lee de izquierda a derecha: cada columna responde a una pregunta. Un ejemplo:",
  "cd.intro.words": "En texto: «{x}»",
  "cd.letter.A": "El número del control, en el orden del recorrido",
  "cd.letter.B": "El código del control, escrito en la baliza",
  "cd.letter.C": "Cuál, cuando hay varios elementos parecidos en el círculo",
  "cd.letter.D": "El elemento del control",
  "cd.letter.E": "Su aspecto, cuando hay que precisarlo",
