  "cd.letter.G": "Dónde está la baliza respecto al elemento",
  "cd.letter.H": "Otra información: primeros auxilios, avituallamiento, control con personal",
  "cd.source": "Números, nombres, descripciones y correspondencias con el mapa: especificación internacional de descripciones de control de la IOF (ISCD 2024). Dibujos de los símbolos de descripción: Purple Pen. Símbolos de mapa: dibujados por Ozimut según ISOM 2017-2 e ISSprOM 2019-2, como en la página «Símbolos del mapa».",
  "cd.col.C": "Columna C · Cuál de los elementos parecidos",
  "cd.col.C.hint": "Cuando hay varios elementos parecidos en el círculo.",
  "cd.col.D": "Columna D · El elemento: {f}",
  "cd.col.D.hint": "El elemento en el centro del círculo, tal como lo representa el mapa. Debajo de cada uno, los símbolos de mapa que la especificación le hace corresponder, con su número: el elemento dibujado con cada uno de ellos en un círculo de control, a la escala del mapa (círculo de 5 mm en bosque, de 6 mm en sprint).",
  "cd.fam.1": "relieve",
  "cd.fam.2": "rocas y piedras",
  "cd.fam.3": "agua y pantanos",
  "cd.fam.4": "vegetación",
  "cd.fam.5": "elementos artificiales",
  "cd.fam.6": "elementos especiales",
  "cd.col.E": "Columna E · Precisiones sobre el elemento",
